<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useUserStoreHook} from '@/store/modules/user';import LinIcon from './LinIcon.vue';import {request} from './service';import './workbench.scss';import '@/components/ReIcon/src/offlineIcon';
const route=useRoute(),router=useRouter(),me=useUserStoreHook(),open=ref(false),dark=ref(localStorage.getItem('lin-admin-dark')==='true');const tabs=ref([{path:'/home',title:'概览'}]);
const links=computed(()=>[{path:'/home',label:'创作概览',icon:'grid'},{path:'/article/articleList',label:'文章管理',icon:'book'},{path:'/article/addArticle',label:'写文章',icon:'pen'},{path:'/moments',label:'说说',icon:'chat'},{path:'/albums',label:'相册',icon:'image'},{path:'/profile',label:'个人设置',icon:'user'},...(me.role===1?[{path:'/registrations',label:'注册审核',icon:'user'},{path:'/taxonomy',label:'分类与标签',icon:'book'},{path:'/comments',label:'评论审核',icon:'heart'},{path:'/authors',label:'作者管理',icon:'user'},{path:'/site-settings',label:'站点设置',icon:'settings'}]:[])]);
function theme(){document.documentElement.classList.toggle('dark',dark.value);localStorage.setItem('lin-admin-dark',String(dark.value));}theme();watch(()=>route.fullPath,()=>{open.value=false;if(!tabs.value.some(t=>t.path===route.fullPath))tabs.value.push({path:route.fullPath,title:String(route.meta.title||'编辑')});if(tabs.value.length>8)tabs.value.splice(1,1);},{immediate:true});
function close(path){tabs.value=tabs.value.filter(t=>t.path!==path);if(route.fullPath===path)router.push(tabs.value.at(-1)?.path||'/home');}
const mood=ref('minimal'),wallpaper=ref('landscape-study');function receiveTheme(e){mood.value=e.detail;}onMounted(async()=>{const p=await request('/api/studio/profile');mood.value=p.theme;wallpaper.value=p.wallpaper;window.addEventListener('lin-theme',receiveTheme);});onBeforeUnmount(()=>window.removeEventListener('lin-theme',receiveTheme));async function switchMood(){try{const p=await request('/api/studio/profile');p.theme=mood.value==='cozy'?'minimal':'cozy';await request('/api/studio/profile','PUT',p);mood.value=p.theme;}catch{}}
</script>
<template><div class="lin-admin" :data-mood="mood" :style="{'--room-wallpaper':'url(/assets/'+wallpaper+'.webp)'}"><button v-if="open" class="admin-scrim" aria-label="关闭导航" @click="open=false"/><aside class="admin-sidebar" :class="{open}"><a href="/admin/" class="admin-brand"><span>L<span>✦</span></span><div>Lin’s Studio<small>灵感有处安放</small></div></a><div class="admin-nav-caption">CREATE YOUR LITTLE WORLD</div><nav><RouterLink v-for="link in links" :key="link.path" :to="link.path" :class="{chosen:route.path===link.path}"><LinIcon :name="link.icon" :size="19"/>{{link.label}}<span v-if="link.path==='/article/addArticle'" class="key-hint">＋</span></RouterLink></nav><div class="sidebar-bottom"><a href="/workspace"><LinIcon name="spark" :size="18"/>生活与兴趣 <span>↗</span></a><a href="/"><LinIcon name="home" :size="18"/>回到随手记 <span>↗</span></a><div class="admin-account"><RouterLink to="/profile"><img class="account-avatar" :src="me.avatar||'/favicon.svg'" alt="我的头像"/></RouterLink><div>{{me.nick_name||'Lin'}}<small>{{me.role===1?'站主 · Administrator':'作者 · Author'}}</small></div><button aria-label="退出登录" @click="me.logOut()"><LinIcon name="logout" :size="17"/></button></div></div></aside><section class="admin-main"><header class="admin-topbar"><div><button class="admin-menu-toggle" aria-label="展开后台导航" @click="open=!open"><LinIcon name="menu"/></button><span class="admin-crumb">工作台 <span>/</span> <b>{{route.meta.title||'概览'}}</b></span></div><div><button class="mood-toggle" @click="switchMood">{{mood==='cozy'?'✦ 私宅主题':'◻ 简约主题'}}</button><span class="studio-status"><i/> 随时可以开始</span><button class="admin-theme-toggle" aria-label="切换后台主题" @click="dark=!dark;theme()"><LinIcon name="moon" :size="18"/></button><a href="/" class="visit-blog">查看网站 ↗</a></div></header><div class="admin-tabs"><div v-for="tab in tabs" :key="tab.path" :class="{active:route.fullPath===tab.path}"><RouterLink :to="tab.path">{{tab.title}}</RouterLink><button v-if="tab.path!=='/home'" @click="close(tab.path)" :aria-label="'关闭'+tab.title">×</button></div></div><main class="admin-content"><RouterView v-slot="{Component}"><Transition name="studio-page" mode="out-in"><component :is="Component" :key="route.fullPath"/></Transition></RouterView></main><footer class="studio-footer">Lin’s Studio <span>留一点空间，给下一次灵感。</span></footer></section></div></template>
